export const VOICE_FILES={"אני: הלו? נועה? מה קרה כל כך מוקדם?": ["./assets/voices/voice176-f0aa56740d896d.mp3"], "נועה: בוקר טוב, אדם. היום אנחנו בודקים את הקורים של העכביש בתא שמונה. אנחנו מנסים לפתח חבלים חזקים שיעזרו לחלץ אנשים. אני צריכה אותך איתנו במעבדה.": ["./assets/voices/voice176-1bced754a54e8e.mp3"], "נועה: תלבש את בגדי העבודה, קח את התיק ואת תג העובד, וסע אלינו. הצוות כבר מתכונן. ואל תיגש לתא לפני שנבדוק שהזכוכית נעולה. נתראה בקרוב.": ["./assets/voices/voice176-2cc83a32ae36cb.mp3"], "בוקר טוב! זה הבית שלך. אתה עובד כעוזר מחקר במעבדת העכבישים. היום הצוות יבדוק קורים חזקים לחילוץ אנשים. גש לארון הבגדים מימין והתארגן לעבודה.": ["./assets/voices/voice176-8b941b1fa26b17.mp3"], "לבשת את בגדי העבודה. עכשיו צריך לקחת את התיק ותג העובד.": ["./assets/voices/voice176-b515b106e808d0.mp3"], "בתיק יש פנס ותג עובד. המעבדה נמצאת באחוזה ישנה מחוץ לעיר. קיבלת הודעה: ״נפגשים ליד תא 08״. כשאתה מוכן, גש לדלת שבין החלונות ולחץ E.": ["./assets/voices/voice176-afeb4e017e9a5f.mp3"], "בדרך לאחוזת המחקר…": ["./assets/voices/voice176-c8c8b76ae04c32.mp3"], "התארגן לעבודה. בגדי העבודה נמצאים בארון, והתיק ותג העובד על השולחן.": ["./assets/voices/voice176-5f5627ef3953ff.mp3"], "רובוט: בוקר טוב! ברוך הבא לאחוזת המחקר. ד״ר נועה מחכה לך משמאל.": ["./assets/voices/voice176-db8a5cc01a7984.mp3"], "נועה: אנחנו מנסים ליצור קורי משי לחילוץ אנשים. אמיר יסביר לך איך מודדים את החוזק.": ["./assets/voices/voice176-91f68bb8398873.mp3"], "אמיר: החוט הזה יכול לשאת משקל עצום. אבל העכביש גדל מאז אתמול. מאיה ביקשה לבדוק אותו שוב.": ["./assets/voices/voice176-6e0d20cd292c68.mp3"], "מאיה: בדיקה קצרה בלבד. אם הגודל משתנה, עוצרים מיד. יואב הכין את המחשב שמימין.": ["./assets/voices/voice176-c79a2fbcb278d8.mp3"], "יואב: החיישנים מוכנים. עבור לכפתור שליד התא והתחל בדיקת משי.": ["./assets/voices/voice176-4c267dbd79b253.mp3"], "מאיה: רגע… המדידה עולה מהר מדי. תעצרו את ההזנה!": ["./assets/voices/voice176-f71d77b1c59d68.mp3"], "המכונית בחניה. גש לדלת הנהג ולחץ E כדי להיכנס.": ["./assets/voices/voice176-5e48e3423bc06d.mp3"], "כריזה: מצב חירום במעבדה. כל אנשי הצוות, להתפנות מיד דרך יציאת החירום!": ["./assets/voices/voice176-0e29efdf34a255.mp3"], "יואב: הדלת נסגרת! רגע, הוא עדיין בפנים!": ["./assets/voices/voice176-85ff814f3c6659.mp3"], "מערכת זיכרון פעילה. תודה שחיברת את הסוללה. אני יחידת תחזוקה 08. בניתי את המסילות, תיקנתי את הדלתות, וזכרתי את מה שהחוקרים העדיפו לשכוח.": ["./assets/voices/voice176-d01b2d21172236.mp3"], "רצינו לעזור לאנשים. קורי עכביש הם קלים וחזקים. החוקרים חלמו על חבלי חילוץ דקים שיצליחו לשאת משקל גדול מתוך בניינים שקרסו.": ["./assets/voices/voice176-b5b3fd246170b5.mp3"], "בתחילת ניסוי 08 היה כאן עכביש קטן. מדדנו כמה משי הוא טווה ובדקנו כל חוט. במשך שבועות הכול נראה רגיל. ואז הביאו דגימה מתחנת המחקר שמתחת לבית.": ["./assets/voices/voice176-e1c05f5528a8e9.mp3"], "הדגימה שינתה את המשי. החוטים נעשו עבים יותר, אבל העכביש התחיל לגדול. ביקשתי להפסיק. המחשב הישן לא אישר את פקודת הכיבוי, וההזנה נמשכה כל הלילה.": ["./assets/voices/voice176-be3d1190a6481c.mp3"], "הוא למד את התנועות שלנו. בזמן שהחוקרים הביטו לרצפה, הוא טיפס לתקרה. על הזכוכית הופיע סדק ראשון. אחר כך שמענו שלוש נקישות מבפנים.": ["./assets/voices/voice176-a1c6f5a5d44e6c.mp3"], "הזכוכית נפרצה. כיביתי את הדלתות כדי לעצור אותו, אבל הוא עבר דרך פתח התחזוקה מעליהן. זו הסיבה שאני אומר לך לבדוק גם את התקרה.": ["./assets/voices/voice176-e1d4739f566291.mp3"], "השוטרים וצוות החילוץ הגיעו בבוקר. הם עקבו אחרי קורים עד למרתף. המצלמה האחרונה הראתה מסדרון ריק, אבל המיקרופון המשיך להקליט שמונה רגליים מתקרבות.": ["./assets/voices/voice176-d539f678d39f9e.mp3"], "הצלחתי להוביל כמה מהחוקרים ליציאה. אחרים נשארו בתחנה התחתונה. מאז אף אחד לא ענה לקריאות שלי. את התיעוד שמרתי במחשב ליד היומן הסודי.": ["./assets/voices/voice176-2beedb4e217de8.mp3"], "פיצלנו את קוד המעלית לשלושה פתקים: בחדר השינה, בחדר האוכל ובחדר המשחקים. אסוף אותם לתיק וקרא את שלוש השורות לפי הסדר.": ["./assets/voices/voice176-9822b034d7a334.mp3"], "במעלית יש קומות 1 ו־2, וכפתור עם סימן שאלה. בשבילו צריך כרטיס גישה. השארנו אותו במעבדה בקומה השנייה. מתחת לבית תמצא את מקור הניסוי. אל תתקרב לבור בלי להסתכל.": ["./assets/voices/voice176-39f1dc7a8b74c8.mp3"], "אם אתה רוצה לצאת, הפנס כבר אצלך. חפש גרזן. שבור את הקרשים בדלת הכניסה. העכביש לא יודע תמיד איפה אתה: פנה מעבר לפינה, התרחק בשקט, והתחבא לפני שיראה אותך.": ["./assets/voices/voice176-e01a320669893e.mp3"], "הסוללה שלי שוב נחלשת. אשב כאן ואשמור על הארכיון. הכפתור האדום יפתח את הדלת. אם תשמע שלוש נקישות... אל תענה.": ["./assets/voices/voice176-d1d24f68e1a11f.mp3"], "ברח! אני אעכב אותו!": ["./assets/voices/voice176-bb867303931b27.mp3"], "איפה אני? איפה כולם?": ["./assets/voices/voice176-0c35c37c8bcdba.mp3"], "מגיש החדשות: הבוקר באחוזת המחקר: מדענים יערכו היום את ניסוי 08 בקורי עכביש.": ["./assets/voices/voice176-cd2ba3daaef87e.mp3"], "מגיש החדשות: הצוות מפתח חבלי חילוץ חזקים וקלים, שיעזרו להציל אנשים ממקומות מסוכנים.": ["./assets/voices/voice176-f9341b8eb06284.mp3"], "מגיש החדשות: החוקרים מסרו שכל הבדיקות יבוצעו בתוך תא זכוכית סגור. נעדכן בהמשך היום.": ["./assets/voices/voice176-a69776a589122d.mp3"], "אני: אני רוצה לראות מה אומרים בחדשות.": ["./assets/voices/voice176-0a460412b060b3.mp3"], "אני: לא... לאן אתה לוקח אותי?": ["./assets/voices/voice176-e56f0f7e3c47d5.mp3"], "אני: זה הבית... אני לא מצליח להישאר ער...": ["./assets/voices/voice176-502c6b3ab9e394.mp3"], "אני: אני מצלם…": ["./assets/voices/voice176-d71192877c9319.mp3"], "אני: הוא תפס את הרגליים שלו!": ["./assets/voices/voice176-21384dc384dc47.mp3"], "רובוט: רוץ למכונית! אני אעצור אותו!": ["./assets/voices/voice176-7a5a73bb7e3958.mp3"], "אני: מה יקרה לרובוט? אני צריך לישון.": ["./assets/voices/voice176-7500e3b26bbd78.mp3"], "חדשות: התקבל תיעוד יוצא דופן מאחוזת המחקר.": ["./assets/voices/voice176-918a677f2fcc24.mp3"], "חדשות: הרובוט עיכב את העכביש ואפשר לחוקר להימלט.": ["./assets/voices/voice176-e40b61218cc59d.mp3"], "חדשות: גורלו של הרובוט עדיין לא ידוע…": ["./assets/voices/voice176-45d14fc06fd72d.mp3"]};
